import React, { useState } from 'react';
import './App.css';

// WelcomePage Component
const WelcomePage = ({ onGetStarted }) => {
  return (
    <div className="welcome-container">
      <header className="welcome-header">
        <div className="header-content">
          <h1>Secure E-Diary</h1>
          <p>Your private thoughts, securely stored</p>
        </div>
      </header>

      <section className="hero-section">
        <div className="hero-content">
          <div className="hero-text">
            <h2>Document Your Life Journey with Complete Privacy</h2>
            <p>Secure E-Diary provides a safe space for your personal reflections with military-grade encryption</p>
            <button className="cta-button" onClick={onGetStarted}>
              Get Started
            </button>
          </div>
          <div className="hero-image">
            <div className="image-placeholder">
              <span role="img" aria-label="Diary">📖</span>
            </div>
          </div>
        </div>
      </section>

      <section className="features-section">
        <h2>Why Choose Secure E-Diary?</h2>
        <div className="features-grid">
          <div className="feature-card">
            <div className="feature-icon">
              <span role="img" aria-label="Security">🔒</span>
            </div>
            <h3>Military-Grade Encryption</h3>
            <p>Your entries are protected with AES-256 encryption, ensuring only you can access your private thoughts.</p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon">
              <span role="img" aria-label="Privacy">👁️</span>
            </div>
            <h3>Complete Privacy</h3>
            <p>We never store your data on external servers. Your diary remains exclusively on your devices.</p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon">
              <span role="img" aria-label="Easy to use">📱</span>
            </div>
            <h3>User-Friendly Interface</h3>
            <p>Enjoy a clean, intuitive design that makes journaling a pleasure rather than a chore.</p>
          </div>
        </div>
      </section>

      <section className="security-section">
        <div className="security-content">
          <div className="security-text">
            <h2>Advanced Security Features</h2>
            <ul>
              <li>End-to-end encryption for all your entries</li>
              <li>Two-factor authentication options</li>
              <li>Biometric login support (fingerprint, face ID)</li>
              <li>Zero-knowledge architecture - we can't access your data</li>
              <li>Automatic backup with encryption</li>
            </ul>
          </div>
          <div className="security-image">
            <div className="image-placeholder">
              <span role="img" aria-label="Security">🛡️</span>
            </div>
          </div>
        </div>
      </section>

      <section className="final-cta">
        <h2>Begin Your Secure Journaling Journey Today</h2>
        <p>Join thousands of users who trust Secure E-Diary with their most personal thoughts</p>
        <button className="cta-button-large" onClick={onGetStarted}>
          Start Your Secure Diary Now
        </button>
      </section>

      <footer className="welcome-footer">
        <p>&copy; 2023 Secure E-Diary. All rights reserved.</p>
      </footer>
    </div>
  );
};

// LoginRegister Component (simplified for demonstration)
const LoginRegister = ({ onLogin, onBack }) => {
  const [isLogin, setIsLogin] = useState(true);
  
  return (
    <div className="auth-container">
      <button className="back-button" onClick={onBack}>← Back to Welcome</button>
      <h2>{isLogin ? 'Login to Your Account' : 'Create an Account'}</h2>
      <form className="auth-form">
        <div className="form-group">
          <label htmlFor="email">Email</label>
          <input type="email" id="email" placeholder="Enter your email" />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password</label>
          <input type="password" id="password" placeholder="Enter your password" />
        </div>
        {!isLogin && (
          <div className="form-group">
            <label htmlFor="confirmPassword">Confirm Password</label>
            <input type="password" id="confirmPassword" placeholder="Confirm your password" />
          </div>
        )}
        <button type="button" className="auth-button" onClick={onLogin}>
          {isLogin ? 'Login' : 'Register'}
        </button>
      </form>
      <p className="auth-toggle">
        {isLogin ? "Don't have an account? " : "Already have an account? "}
        <span onClick={() => setIsLogin(!isLogin)}>
          {isLogin ? 'Register' : 'Login'}
        </span>
      </p>
    </div>
  );
};

// RoleSelection Component (simplified for demonstration)
const RoleSelection = ({ onRoleSelect, onBack }) => {
  return (
    <div className="role-container">
      <button className="back-button" onClick={onBack}>← Back to Login</button>
      <h2>Select Your Role</h2>
      <div className="role-options">
        <div className="role-card" onClick={() => onRoleSelect('user')}>
          <h3>User</h3>
          <p>Create and manage your personal diary entries</p>
        </div>
        <div className="role-card" onClick={() => onRoleSelect('admin')}>
          <h3>Administrator</h3>
          <p>Manage system settings and user accounts</p>
        </div>
      </div>
    </div>
  );
};

// Main App Component
function App() {
  const [currentView, setCurrentView] = useState('welcome');
  const [userRole, setUserRole] = useState(null);

  const handleGetStarted = () => {
    setCurrentView('login');
  };

  const handleBackToWelcome = () => {
    setCurrentView('welcome');
  };

  const handleLogin = () => {
    setCurrentView('roleSelection');
  };

  const handleRoleSelect = (role) => {
    setUserRole(role);
    alert(`Selected role: ${role}. Redirecting to main application...`);
  };

  return (
    <div className="app">
      {currentView === 'welcome' && (
        <WelcomePage onGetStarted={handleGetStarted} />
      )}
      
      {currentView === 'login' && (
        <LoginRegister 
          onLogin={handleLogin}
          onBack={handleBackToWelcome}
        />
      )}
      
      {currentView === 'roleSelection' && (
        <RoleSelection 
          onRoleSelect={handleRoleSelect}
          onBack={() => setCurrentView('login')}
        />
      )}
    </div>
  );
}

export default App;
